export class OfficeChat {
  constructor(model,{onSend=async()=>{},onTalk=async()=>{},onWalk=()=>{},toast=()=>{}}={}){
    this.model=model;this.onSend=onSend;this.onTalk=onTalk;this.onWalk=onWalk;this.toast=toast;this.tab='overheard';this.room=null;this.readAloud=false;this.localReplies=[];
    this.node=document.createElement('aside');this.node.className='chat-dock hidden';this.node.setAttribute('aria-label','Office chat window');
    this.node.innerHTML='<div class="chat-heading"><div><span class="status-dot"></span><strong>Office chatter</strong><small id="chat-presence">The office has opinions.</small></div><button id="chat-close" aria-label="Close chat">×</button></div><div class="chat-tabs" role="tablist"><button role="tab" aria-selected="true" data-tab="overheard">Overheard</button><button role="tab" aria-selected="false" data-tab="team">Team</button><button role="tab" aria-selected="false" data-tab="talk">Talk to NPCs</button></div><div id="chat-messages" class="chat-messages" role="log" aria-live="polite"></div><div id="npc-chat-controls" class="hidden"><label class="field-label" for="npc-chat-select">WHO WOULD YOU LIKE TO TALK TO?</label><select id="npc-chat-select"></select><div class="npc-chat-actions"><button data-conversation="greet">Say hello</button><button data-conversation="help">Offer help</button><button data-conversation="quiet">Ask for quiet</button></div><p class="field-hint">Walk nearby to talk. Choose someone here to find them.</p></div><form id="chat-form" class="chat-form hidden"><label class="sr-only" for="chat-input">Message your team</label><input id="chat-input" maxlength="160" placeholder="Say something to your team…" autocomplete="off"><button type="submit" aria-label="Send chat message">↗</button></form><div class="chat-bottom"><button id="chat-read" aria-pressed="false">Read banter aloud: off</button><span>No microphones required.</span></div>';
    document.body.append(this.node);this.messages=this.node.querySelector('#chat-messages');this.npcSelect=this.node.querySelector('#npc-chat-select');
    this.node.querySelector('#chat-close').onclick=()=>this.node.classList.add('hidden');
    this.node.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>this.setTab(b.dataset.tab));
    this.node.querySelector('#chat-form').onsubmit=async e=>{e.preventDefault();const input=this.node.querySelector('#chat-input'),text=input.value.trim();if(!text)return;const button=e.submitter;button.disabled=true;try{await this.onSend(text);input.value='';}catch(error){this.toast(error.message);}finally{button.disabled=false;input.focus();}};
    this.node.querySelectorAll('[data-conversation]').forEach(b=>b.onclick=()=>this.talk(b.dataset.conversation));
    this.npcSelect.onchange=()=>{const n=this.model.state.npcs.find(n=>n.id===this.npcSelect.value);if(n)this.onWalk(n.id);};
    this.node.querySelector('#chat-read').onclick=()=>{if(!('speechSynthesis'in window)){this.toast('Read-aloud is unavailable in this browser. The full banter feed is still here.');return;}this.readAloud=!this.readAloud;this.node.querySelector('#chat-read').textContent='Read banter aloud: '+(this.readAloud?'on':'off');this.node.querySelector('#chat-read').setAttribute('aria-pressed',String(this.readAloud));if(!this.readAloud)speechSynthesis.cancel();this.spokenIds=new Set((this.model.state.banter||[]).map(x=>x.id));};
  }
  open(tab='overheard'){this.node.classList.remove('hidden');this.setTab(tab);}
  setTab(tab){this.tab=tab;this.renderKey='';this.node.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.tab===tab)));this.node.querySelector('#chat-form').classList.toggle('hidden',tab!=='team');this.node.querySelector('#npc-chat-controls').classList.toggle('hidden',tab!=='talk');this.render(this.room);}
  appendMessage(entry){const line=document.createElement('div');line.className='chat-line '+(entry.kind||'');const heading=document.createElement('div'),who=document.createElement('strong'),time=document.createElement('span');who.textContent=entry.speaker||entry.name||'The office';const value=Number(entry.time)||0;time.textContent=value>1e10?new Date(value).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}):'OVERHEARD';heading.append(who,time);const text=document.createElement('p');text.textContent=entry.text;line.append(heading,text);this.messages.append(line);}
  async talk(choice){
    const id=this.npcSelect.value,n=this.model.state.npcs.find(n=>n.id===id);if(!n)return;
    if(Math.hypot(n.x-this.model.state.player.x,n.y-this.model.state.player.y)>120){this.onWalk(id);this.toast('Walking to '+n.name+'. Speak again when you arrive.');return;}
    try{const result=await this.onTalk(id,choice);let text=result.message||result.text||'Thanks for checking in.';if(text.startsWith(n.name+': '))text=text.slice(n.name.length+2);this.localReplies.push({id:'reply-'+Date.now(),speaker:n.name,text,time:Date.now(),kind:'reply'});this.localReplies=this.localReplies.slice(-20);this.renderKey='';this.render(this.room);}catch(error){this.toast(error.message);}
  }
  render(room=null){
    this.room=room;this.node.querySelector('#chat-presence').textContent=room?(room.players?.length||1)+' coworkers online · '+room.code:'The office has opinions.';
    const banter=[...(this.model.state.banter||[])].reverse();
    if(this.readAloud){this.spokenIds??=new Set();for(const e of banter){if(!this.spokenIds.has(e.id)){this.spokenIds.add(e.id);if(!speechSynthesis.speaking&&e.text){const u=new SpeechSynthesisUtterance((e.speaker||e.name||'Someone')+' says: '+e.text);u.rate=1.06;u.volume=.65;speechSynthesis.speak(u);}}}}
    let entries=this.tab==='overheard'?banter:this.tab==='team'?(room?.chat||[]):this.localReplies;
    const key=this.tab+'|'+entries.map(e=>e.id).join('|')+'|'+!!room;
    if(key!==this.renderKey){const bottom=this.messages.scrollHeight-this.messages.scrollTop-this.messages.clientHeight<60;this.messages.replaceChildren();if(!entries.length){const p=document.createElement('p');p.className='chat-empty';p.textContent=this.tab==='team'?(room?'Your team has entered the chat. Say hello.':'Open or join an online office to chat with other players.'):this.tab==='talk'?'Pick a coworker, walk nearby, and start a conversation.':'The office is warming up. Someone will have something to say.';this.messages.append(p);}else entries.slice(-40).forEach(e=>this.appendMessage(e));if(bottom)this.messages.scrollTop=this.messages.scrollHeight;this.renderKey=key;}
    const names=(this.model.state.npcs||[]).filter(n=>!n.hidden);const npcKey=names.map(n=>n.id).join('|');if(npcKey!==this.npcKey){const current=this.npcSelect.value;this.npcSelect.replaceChildren();for(const n of names){const o=document.createElement('option');o.value=n.id;o.textContent=n.name+(n.role==='visitor'?' · gym visitor':'');this.npcSelect.append(o);}if(names.some(n=>n.id===current))this.npcSelect.value=current;this.npcKey=npcKey;}
    const online=!!room;this.node.querySelector('#chat-input').disabled=!online;this.node.querySelector('#chat-form button').disabled=!online;
  }
}
